contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to) public payable {
        uint256 beforeC = address(c).balance;
        uint256 beforeTo = to.balance;
        bool reverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 afterC = address(c).balance;
        uint256 afterTo = to.balance;
        assert(reverted ? afterC == beforeC : (afterC == 0 && afterTo == beforeTo + beforeC));
    }

    receive() external payable {}
}

